--!nocheck
return function()
 local Players=game:GetService('Players')
 local Profile=require(script.Parent.Parent.Services.PlayerDataService)
 local Fake=require(script.Parent.Support.FakePlayerProfileBackend)
 local Team=require(script.Parent.Parent.Services.ChariotTeamService)
 local Cart=require(script.Parent.Parent.Services.CartService)
 local Storage=require(script.Parent.Parent.Systems.BaseStorageSystem)
 local Currency=require(script.Parent.Parent.Systems.CurrencySystem)
 local Carts=require(game.ReplicatedStorage.Shared.Config.Carts)
 local Catalog=require(game.ReplicatedStorage.Shared.Config.BrainrotCatalog)
 local function withShieldFixture(fn)
  local rs=game.ReplicatedStorage local previous=rs:GetAttribute('ShieldDevelopmentFixturesEnabled')
  rs:SetAttribute('ShieldDevelopmentFixturesEnabled',true)
  local def=table.clone(Catalog.Get('BRT_001'))def.id='FIXTURE_SHIELD_TEAM_TRANSACTION'def.displayName='Shield transaction fixture'
  def.developmentFixture=true def.spawnEnabled=false def.launchStatus='Teased'
  def.chariotEffect={effect='Shield',contribution=1,contributors=3,amplifierTarget='Shield'}
  Catalog.RegisterDevelopmentFixtures({def})
  local ok,failure=xpcall(function()fn(def)end,debug.traceback)
  Catalog.ClearDevelopmentFixtures()rs:SetAttribute('ShieldDevelopmentFixturesEnabled',previous)
  assert(ok,failure)
 end
 local function fixture(fn)
  Team:Destroy()Profile:_ResetForTests()local now=1000 local operation=0
  Profile:Init({Backend=Fake.new({Now=function()return now end}),UnixNow=function()return now end,MonotonicNow=function()return now end,Wait=function(dt)now+=dt end,Random=function()return 0 end,GenerateOperationId=function(prefix)operation+=1 return prefix..operation end,KickOnFailure=false})
  Currency:_ResetForTests(Profile)
  local p={Name='Phase9Fixture',UserId=97501,Parent=Players,Attributes={}}
  function p:SetAttribute(k,v)self.Attributes[k]=v end function p:GetAttribute(k)return self.Attributes[k]end function p:Kick()end
  assert(Profile:LoadPlayerAsync(p).ok,"Fixture profile load failed")
  local definition for _,v in Carts do if type(v)=='table' and v.AssetName=='ScrapChariot' then definition=v break end end assert(definition,"Starter cart missing")
  local model=Instance.new('Model')local root=Instance.new('Part')root.Name='Root'root.Parent=model model.PrimaryPart=root model.Parent=workspace
  local record={Model=model,Generation=7,CartId=definition.Id,PerformanceResult={resolvedSpeed=definition.MaxTravelSpeed,teamSpeedRatio=1}}
  local oldContext,oldCart,oldReconcile,oldStorage=Team.Context,Cart.GetCartRecord,Cart.ReconcileOwnerPerformance,Storage.GetStorageForPlayer
  Team.Context=function()return true,nil end Cart.GetCartRecord=function(_,who)return who==p and record or nil end Cart.ReconcileOwnerPerformance=function()end Storage.GetStorageForPlayer=function()return nil end
  Team:_TestSetClock(function()return now end)
  Profile:CommitMutation(p,function(d)
   d.Economy.Balance=500300000.25
   for i=1,6 do local id='individual'..i d.Collection.BrainrotInstances[id]={speciesId='BRT_001'}d.Base.Slots[tostring(i)].brainrotId=id d.Base.Slots[tostring(i)].accumulatedCash=i+.25 end
   return true,{ok=true}
  end)
  Team:Reconcile(p,true)
  local sequence=0
  local function request(action,fields)
   now+=1.1 sequence+=1 local state=Team:Snapshot(p)
   local payload=fields or {}payload.operation=action payload.requestId=payload.requestId or 'request'..sequence payload.session=payload.session or state.session payload.cartGeneration=7 payload.expectedTeamRevision=payload.expectedTeamRevision or state.teamRevision
   return Team:Request(p,payload),payload
  end
  local ok,err=xpcall(function()fn(p,request,function()return Profile:GetReadableData(p)end,function()return now end,oldContext,record)end,debug.traceback)
  Team.Context=oldContext Cart.GetCartRecord=oldCart Cart.ReconcileOwnerPerformance=oldReconcile Storage.GetStorageForPlayer=oldStorage model:Destroy()Team:Destroy()Profile:_ResetForTests()Currency:_ResetForTests()
  assert(ok,err)
 end
 describe('Phase 9 real mutation boundary',function()
  it('another ready player cannot mutate the owner cart or debit its wallet',function()fixture(function(_p,_request,data,_now,realContext)
   local guest={Name='OtherPlayer',UserId=97502,Parent=Players,Attributes={}}
   function guest:SetAttribute(k,v)self.Attributes[k]=v end function guest:GetAttribute(k)return self.Attributes[k]end function guest:Kick()end
   assert(Profile:LoadPlayerAsync(guest).ok,'Guest fixture profile failed to load')
   local ready=require(script.Parent.Parent.Services.PlayerWorldLifecycle)
   local oldReady=ready.IsReady local bypass=Team.Context
   ready.IsReady=function()return true end Team.Context=realContext
   local snapshot=Team:Snapshot(guest) local before=data().Economy.Balance
   local result=Team:Request(guest,{operation='Buy',slot=3,configVersion=1,requestId='wrong-owner',session=snapshot.session,cartGeneration=7})
   Team.Context=bypass ready.IsReady=oldReady
   expect(result.ok).to.equal(false)expect(result.code).to.equal('WRONG_CART')
   expect(data().Economy.Balance).to.equal(before)expect(data().ChariotTeam.PurchasedExtraSlots).to.equal(0)
   expect(Profile:GetReadableData(guest).ChariotTeam.PurchasedExtraSlots).to.equal(0)
  end)end)
  it('a former session cannot change saved assignments',function()fixture(function(p,request,data)
   request('Equip',{slot=1,individualId='individual1'})
   local snapshot=Team:Snapshot(p)
   local result=Team:Request(p,{operation='Unequip',slot=1,expectedIndividualId='individual1',requestId='former-session',session=snapshot.session+1,cartGeneration=7,expectedTeamRevision=snapshot.teamRevision})
   expect(result.code).to.equal('STALE_STATE')expect(data().ChariotTeam.Assignments['1']).to.equal('individual1')
  end)end)
  it('equip leaves the owned record platform and fractional cash unchanged',function()fixture(function(_p,request,data)local r=request('Equip',{slot=1,individualId='individual1'})expect(r.ok).to.equal(true)expect(data().Base.Slots['1'].brainrotId).to.equal('individual1')expect(data().Base.Slots['1'].accumulatedCash).to.equal(1.25)expect(data().ChariotTeam.Assignments['1']).to.equal('individual1')expect(data().Collection.BrainrotInstances.individual1.speciesId).to.equal('BRT_001')end)end)
  it('rejects duplicate identity while allowing separate species copies',function()fixture(function(p,request,_data)expect(request('Equip',{slot=1,individualId='individual1'}).ok).to.equal(true)expect(request('Equip',{slot=2,individualId='individual1'}).code).to.equal('ALREADY_EQUIPPED')expect(request('Equip',{slot=2,individualId='individual2'}).ok).to.equal(true)expect(Team:Snapshot(p).stats.count).to.equal(2)end)end)
  it('failed replacement preserves the outgoing teammate',function()fixture(function(_p,request,data)request('Equip',{slot=1,individualId='individual1'})local r=request('Replace',{slot=1,individualId='absent',expectedIndividualId='individual1'})expect(r.ok).to.equal(false)expect(data().ChariotTeam.Assignments['1']).to.equal('individual1')end)end)
  it('failed pickup transaction preserves assignment and cash',function()fixture(function(p,request,data)request('Equip',{slot=1,individualId='individual1'})Profile:CommitMutation(p,function(d)d.Base.Slots['1'].brainrotId=nil return false,{ok=false}end)expect(data().ChariotTeam.Assignments['1']).to.equal('individual1')expect(data().Base.Slots['1'].accumulatedCash).to.equal(1.25)end)end)
  it('successful pickup clears inside the same revision without deleting ownership',function()fixture(function(p,request,data)request('Equip',{slot=1,individualId='individual1'})local before=Profile:GetDiagnostics(p).currentRevision Profile:CommitMutation(p,function(d)d.Base.Slots['1'].brainrotId=nil return true,{ok=true}end)expect(data().ChariotTeam.Assignments['1']).to.equal(false)expect(Profile:GetDiagnostics(p).currentRevision).to.equal(before+1)expect(data().Collection.BrainrotInstances.individual1.speciesId).to.equal('BRT_001')expect(data().Base.Slots['1'].accumulatedCash).to.equal(1.25)end)end)
  it('sale removes equipment reference exactly with ownership and existing wallet credit',function()fixture(function(p,request,data)request('Equip',{slot=1,individualId='individual1'})local balance=data().Economy.Balance Profile:CommitMutation(p,function(d)d.Base.Slots['1'].brainrotId=nil d.Collection.BrainrotInstances.individual1=nil d.Economy.Balance+=162000 return true,{ok=true}end)expect(data().ChariotTeam.Assignments['1']).to.equal(false)expect(data().Economy.Balance).to.equal(balance+162000)expect(data().Base.Slots['1'].accumulatedCash).to.equal(1.25)end)end)
  it('returning to a platform does not auto-equip',function()fixture(function(p,request,data)request('Equip',{slot=1,individualId='individual1'})Profile:CommitMutation(p,function(d)d.Base.Slots['1'].brainrotId=nil return true,{ok=true}end)Profile:CommitMutation(p,function(d)d.Base.Slots['1'].brainrotId='individual1'return true,{ok=true}end)expect(data().ChariotTeam.Assignments['1']).to.equal(false)end)end)
  it('exact old offer and repeated request never debit twice',function()fixture(function(p,request,data)local r,payload=request('Buy',{slot=3,configVersion=1})expect(r.ok).to.equal(true)local balance=data().Economy.Balance local retry=Team:Request(p,payload)expect(retry.code).to.equal('ALREADY_APPLIED')request('Buy',{slot=3,configVersion=1})expect(data().Economy.Balance).to.equal(balance)expect(data().ChariotTeam.PurchasedExtraSlots).to.equal(1)end)end)
  it('one request id cannot be reused for another payload',function()fixture(function(p,request,data)local _,payload=request('Buy',{slot=3,configVersion=1})payload.slot=4 expect(Team:Request(p,payload).code).to.equal('INVALID_REQUEST')expect(data().ChariotTeam.PurchasedExtraSlots).to.equal(1)end)end)
  it('stale unequip cannot clear a later assignment including ABA',function()fixture(function(p,request,data)
   request('Equip',{slot=1,individualId='individual1'})local _,old=request('Unequip',{slot=1,expectedIndividualId='individual1'})request('Equip',{slot=1,individualId='individual1'})
   expect(Team:Request(p,old).code).to.equal('ALREADY_APPLIED')expect(data().ChariotTeam.Assignments['1']).to.equal('individual1')
   old.requestId='expired-cache-retry' expect(Team:Request(p,old).code).to.equal('STALE_STATE')expect(data().ChariotTeam.Assignments['1']).to.equal('individual1')
  end)end)
  it('wrong expected occupant cannot remove a replacement',function()fixture(function(_p,request,data)request('Equip',{slot=1,individualId='individual1'})request('Replace',{slot=1,individualId='individual2',expectedIndividualId='individual1'})expect(request('Unequip',{slot=1,expectedIndividualId='individual1'}).ok).to.equal(false)expect(data().ChariotTeam.Assignments['1']).to.equal('individual2')end)end)
  it('income mutation does not stale team revision',function()fixture(function(p,request,_data)local revision=Team:Snapshot(p).teamRevision Profile:CommitMutation(p,function(d)d.Base.Slots['1'].accumulatedCash+=.5 return true,{ok=true}end)Team:Reconcile(p,false)expect(Team:Snapshot(p).teamRevision).to.equal(revision)expect(request('Equip',{slot=1,individualId='individual1',expectedTeamRevision=revision}).ok).to.equal(true)end)end)
  it('purchase and wallet are stored in the same actual save snapshot',function()fixture(function(p,request,data)request('Buy',{slot=3,configVersion=1})local save=require(script.Parent.Parent.Data.PlayerProfileSchema).CreateSaveSnapshot(data())expect(save.ChariotTeam.PurchasedExtraSlots).to.equal(1)expect(save.Economy.Balance).to.equal(300000.25)expect(Profile:GetDiagnostics(p).dirty).to.equal(true)end)end)
  it('rejects malformed finite-slot and extra nested payloads',function()fixture(function(_p,request,_data)expect(request('Buy',{slot=0/0,configVersion=1}).code).to.equal('INVALID_REQUEST')expect(request('Equip',{slot=1.5,individualId='individual1'}).code).to.equal('INVALID_REQUEST')expect(request('Equip',{slot=1,individualId='individual1',extra={huge=true}}).code).to.equal('INVALID_REQUEST')end)end)
  it('future data-only Shield definitions use the same saved individual equip and roster path',function()
   withShieldFixture(function(def)fixture(function(p,request,data)
    local seeded=Profile:CommitMutation(p,function(d)d.Collection.BrainrotInstances.individual1.speciesId=def.id return true,{ok=true}end)
    assert(seeded.ok and seeded.committed,'Fixture definition mutation must commit: '..tostring(seeded.code)..' '..tostring(seeded.reason))
    expect(data().Collection.BrainrotInstances.individual1.speciesId).to.equal(def.id)
    Team:Reconcile(p,true)
    expect(request('Equip',{slot=1,individualId='individual1'}).ok).to.equal(true)
    local snapshot=Team:Snapshot(p)expect(snapshot.stats.shieldCapacity).to.equal(1)
    local row for _,candidate in snapshot.rows do if candidate.individualId=='individual1'then row=candidate end end
    expect(row.effect).to.equal('Shield')expect(row.contribution).to.equal(1)expect(row.grant).to.equal(3)expect(row.amplifierTarget).to.equal('Shield')
    expect(row.effectDescription).to.equal('Blocks a cargo hit and protects your cargo for 5 seconds. Refills at your base.')
    expect(data().Base.Slots['1'].brainrotId).to.equal('individual1')expect(data().Base.Slots['1'].accumulatedCash).to.equal(1.25)
    expect(data().Collection.BrainrotInstances.individual1.speciesId).to.equal(def.id)
   end)end)
  end)
  it('publishes current-cart Shield reserve separately from maximum preview capacity',function()
   withShieldFixture(function(def)fixture(function(p,request,data,_now,_context,record)
    local seeded=Profile:CommitMutation(p,function(d)d.Collection.BrainrotInstances.individual1.speciesId=def.id return true,{ok=true}end)
    assert(seeded.ok and seeded.committed,'Fixture definition mutation must commit: '..tostring(seeded.code)..' '..tostring(seeded.reason))
    expect(data().Collection.BrainrotInstances.individual1.speciesId).to.equal(def.id)
    Team:Reconcile(p,true)request('Equip',{slot=1,individualId='individual1'})
    local model=record.Model
    model:SetAttribute('ShieldCartGeneration',7)model:SetAttribute('ShieldCapacity',1)model:SetAttribute('ShieldRemaining',0)
    model:SetAttribute('ShieldProtectionExpiresAt',1005)model:SetAttribute('ShieldRevision',12)model:SetAttribute('ShieldLifecycleId','owner-session-expedition')
    local state=Team:Snapshot(p)
    expect(state.stats.shieldCapacity).to.equal(1)expect(state.shield.capacity).to.equal(1)expect(state.shield.remaining).to.equal(0)
    expect(state.shield.protectedUntil).to.equal(1005)expect(state.shield.revision).to.equal(12)expect(state.shield.lifecycleId).to.equal('owner-session-expedition')
    model:SetAttribute('ShieldCartGeneration',6)
    local stale=Team:Snapshot(p)expect(stale.shield.capacity).to.equal(1)expect(stale.shield.remaining).to.equal(0)expect(stale.shield.protectedUntil).to.equal(0)
   end)end)
  end)
  it('a rejected replacement preserves reserve attributes and sends no derived-change notification',function()
   withShieldFixture(function(def)fixture(function(p,request,data,_now,_context,record)
    local seeded=Profile:CommitMutation(p,function(d)d.Collection.BrainrotInstances.individual1.speciesId=def.id return true,{ok=true}end)
    assert(seeded.ok and seeded.committed,'Fixture definition mutation must commit: '..tostring(seeded.code)..' '..tostring(seeded.reason))
    expect(data().Collection.BrainrotInstances.individual1.speciesId).to.equal(def.id)
    Team:Reconcile(p,true)request('Equip',{slot=1,individualId='individual1'})
    local model=record.Model model:SetAttribute('ShieldCapacity',1)model:SetAttribute('ShieldRemaining',1)model:SetAttribute('ShieldProtectionExpiresAt',1005)
    local notifications=0 local connection=Team:SubscribeReconciled(function()notifications+=1 end)
    expect(request('Replace',{slot=1,individualId='absent',expectedIndividualId='individual1'}).ok).to.equal(false)
    expect(data().ChariotTeam.Assignments['1']).to.equal('individual1')expect(model:GetAttribute('ShieldRemaining')).to.equal(1)
    expect(model:GetAttribute('ShieldProtectionExpiresAt')).to.equal(1005)expect(notifications).to.equal(0)
    expect(request('Unequip',{slot=1,expectedIndividualId='individual1'}).ok).to.equal(true)expect(notifications).to.equal(1)
    connection:Disconnect()
   end)end)
  end)
  it('transient fixture ownership is valid only while its guarded catalogue registration is active',function()
   withShieldFixture(function(def)fixture(function(p,_request,data)
    local seeded=Profile:CommitMutation(p,function(d)d.Collection.BrainrotInstances.individual1.speciesId=def.id return true,{ok=true}end)
    assert(seeded.ok and seeded.committed,'Fixture ownership must commit before validating the guard')
    local schema=require(script.Parent.Parent.Data.PlayerProfileSchema)
    expect(schema.ValidateLoaded(data())).to.equal(true)
    game.ReplicatedStorage:SetAttribute('ShieldDevelopmentFixturesEnabled',nil)
    local valid,reason=schema.ValidateLoaded(data())
    game.ReplicatedStorage:SetAttribute('ShieldDevelopmentFixturesEnabled',true)
    expect(valid).to.equal(false)expect(reason).to.equal('INVALID_OWNED_BRAINROT')
    expect(data().Collection.BrainrotInstances.individual1.speciesId).to.equal(def.id)
    expect(data().Base.Slots['1'].brainrotId).to.equal('individual1')expect(data().Base.Slots['1'].accumulatedCash).to.equal(1.25)
    expect(schema.ValidateLoaded(data())).to.equal(true)
   end)end)
  end)
  it('preserves concurrent playtime through Shield equipment and the actual save boundary',function()
   withShieldFixture(function(def)fixture(function(p,request,data)
    local seeded=Profile:CommitMutation(p,function(d)
     d.Collection.BrainrotInstances.individual1.speciesId=def.id
     d.WorldReadyPlaytimeSeconds=900.125
     return true,{ok=true}
